CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA auth; CREATE SCHEMA storage; CREATE SCHEMA shop_manager;
CREATE TABLE auth.users(id uuid PRIMARY KEY);
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('test.user',true),'')::uuid $$;
CREATE TABLE public.vehicles(id uuid PRIMARY KEY,owner_user_id uuid REFERENCES auth.users(id),vin text,is_public boolean default false);
CREATE TABLE public.user_garage_vehicles(id uuid PRIMARY KEY,user_id uuid);
CREATE TABLE public.rides(id uuid PRIMARY KEY,user_id uuid,status text);
CREATE TYPE public.service_record_type AS ENUM ('other','brake_service');
CREATE TABLE public.vehicle_service_records(id uuid PRIMARY KEY,vehicle_id uuid,receipt_url text,performed_at date,mileage_km integer,title text,service_type public.service_record_type,created_by uuid);
CREATE TABLE public.customer_accounts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid UNIQUE,display_name text);
CREATE TABLE shop_manager.shops(id uuid PRIMARY KEY,name text,business_id uuid);
CREATE TABLE shop_manager.customers(id uuid PRIMARY KEY,shop_id uuid);
CREATE TABLE shop_manager.vehicles(id uuid PRIMARY KEY,customer_id uuid,vin text);
CREATE TABLE shop_manager.profiles(id uuid PRIMARY KEY,user_id uuid,shop_id uuid);
CREATE TABLE shop_manager.roles(id uuid PRIMARY KEY,name text);
CREATE TABLE shop_manager.user_roles(user_id uuid,role_id uuid);
CREATE TABLE shop_manager.expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),shop_id uuid,amount numeric,expense_date date,description text,created_by uuid);
CREATE FUNCTION shop_manager.employee_allowed_modules() RETURNS text[] LANGUAGE sql STABLE AS $$ SELECT ARRAY['vehicles']::text[] $$;
CREATE FUNCTION shop_manager.is_shop_operations_manager(_uid uuid,_shop uuid) RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT EXISTS(SELECT 1 FROM shop_manager.profiles WHERE user_id=_uid AND shop_id=_shop) $$;
CREATE TABLE public.installed_components(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),business_id uuid,shop_manager_vehicle_id uuid,public_vehicle_id uuid,name_snapshot text,installed_at timestamptz,installed_odometer_km integer,installer_user_id uuid);
CREATE TABLE public.vehicle_history_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),vehicle_id uuid,customer_account_id uuid,business_id uuid,event_type text,occurred_at timestamptz,odometer_km integer,title text,summary text,source_table text,source_id uuid,verification_status text,public_summary_allowed boolean DEFAULT false,actor_id uuid,metadata jsonb);
CREATE UNIQUE INDEX vehicle_history_events_source_idx ON public.vehicle_history_events(source_table,source_id,event_type) WHERE source_id IS NOT NULL;
ALTER TABLE public.vehicle_history_events ENABLE ROW LEVEL SECURITY;
CREATE TABLE storage.buckets(id text PRIMARY KEY,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
CREATE TABLE storage.objects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),bucket_id text,name text);
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION storage.foldername(name text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT string_to_array(name,'/') $$;
GRANT USAGE ON SCHEMA auth,storage,shop_manager TO authenticated,anon;
GRANT EXECUTE ON FUNCTION auth.uid() TO authenticated,anon;
GRANT SELECT,INSERT,DELETE ON storage.objects TO authenticated;
GRANT SELECT ON public.vehicles TO authenticated,anon;
GRANT SELECT ON public.vehicle_history_events TO authenticated,anon;
